+		for _, reported := range vc.VulnCheckReportedExploitation {
+			entry.VulnCheck.ReportedExploitation = append(entry.VulnCheck.ReportedExploitation, models.VulnCheckReportedExploitation{
+				URL: reported.URL, DateAdded: reported.DateAdded,
+			})
+		}
+		result = append(result, entry)
+	}
